$root=$PSScriptRoot; $l=New-Object Net.HttpListener; $l.Prefixes.Add("http://localhost:8080/"); $l.Start(); $m=@{".html"="text/html; charset=utf-8";".css"="text/css";".js"="application/javascript"}; while($l.IsListening){$c=$l.GetContext(); $p=[Uri]::UnescapeDataString($c.Request.Url.LocalPath).TrimStart('/').Replace('/', '\'); if([string]::IsNullOrEmpty($p)){$p="index.html"}; if($p.EndsWith('\')){$p += "index.html"}; if([IO.Path]::GetExtension($p) -eq ""){$p += "\index.html"}; $f=[IO.Path]::GetFullPath((Join-Path $root $p)); if($f.StartsWith($root, [StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $f -PathType Leaf)){ $ext=[IO.Path]::GetExtension($f); if($m.ContainsKey($ext)){$c.Response.ContentType=$m[$ext]} else {$c.Response.ContentType="application/octet-stream"}; $b=[IO.File]::ReadAllBytes($f); $c.Response.OutputStream.Write($b,0,$b.Length)} else {$c.Response.StatusCode=404}; $c.Response.Close()}
